// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// SearchPluginCatalog Search the plugin catalog
	// (GET /plugin-catalog)
	SearchPluginCatalog(ctx context.Context, request SearchPluginCatalogRequestObject) (SearchPluginCatalogResponseObject, error)
	// ListPluginSources List plugin sources
	// (GET /plugin-sources)
	ListPluginSources(ctx context.Context, request ListPluginSourcesRequestObject) (ListPluginSourcesResponseObject, error)
	// ListPlugins List installed plugins
	// (GET /plugins)
	ListPlugins(ctx context.Context, request ListPluginsRequestObject) (ListPluginsResponseObject, error)
	// InstallPlugin Install a plugin
	// (POST /plugins)
	InstallPlugin(ctx context.Context, request InstallPluginRequestObject) (InstallPluginResponseObject, error)
	// UninstallPlugin Uninstall a plugin
	// (DELETE /plugins/{plugin_id})
	UninstallPlugin(ctx context.Context, request UninstallPluginRequestObject) (UninstallPluginResponseObject, error)
	// GetPlugin Get a plugin
	// (GET /plugins/{plugin_id})
	GetPlugin(ctx context.Context, request GetPluginRequestObject) (GetPluginResponseObject, error)
	// DisablePlugin Disable a plugin
	// (POST /plugins/{plugin_id}/disable)
	DisablePlugin(ctx context.Context, request DisablePluginRequestObject) (DisablePluginResponseObject, error)
	// EnablePlugin Enable a plugin
	// (POST /plugins/{plugin_id}/enable)
	EnablePlugin(ctx context.Context, request EnablePluginRequestObject) (EnablePluginResponseObject, error)
	// IssuePanelToken Issue a panel token
	// (POST /plugins/{plugin_id}/panel-token)
	IssuePanelToken(ctx context.Context, request IssuePanelTokenRequestObject) (IssuePanelTokenResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

